[standards/infrastructure/iac/STD-INFRA-IAC-006-linting.md#required-tflinthcl-template]

### Required `.tflint.hcl` Template

```hcl
# iac/terraform/formations/aws/<formation-name>/.tflint.hcl

plugin "aws" {
  enabled = true
  version = "0.32.0"    # Pin to a specific version — no floating versions per REQ-IAC-006-06d
  source  = "github.com/terraform-linters/tflint-ruleset-aws"
}

rule "terraform_required_version" {
  enabled = true    # REQ-IAC-006-05d: required_version must be declared
}

rule "terraform_required_providers" {
  enabled = true    # REQ-IAC-006-05: all providers including random must declare version constraints
}

rule "terraform_naming_convention" {
  enabled = true    # snake_case for all resource, variable, and output names
}

rule "terraform_deprecated_interpolation" {
  enabled = true    # Flags deprecated "${var.x}" single-expression interpolation
}

rule "terraform_unused_declarations" {
  enabled = true    # Warning level — must be resolved before production deployment
}

rule "terraform_module_pinned_source" {
  enabled          = true
  # Suppressed: All module sources use git-SSH URLs with semver tags per STD-INFRA-IAC-002.
  # pfe-iac-modules tags are PE-managed and immutable; commit hash pinning is not required.
  # git-SSH URLs cannot be resolved by tflint in CI — call_module_type=none prevents resolution errors.
  call_module_type = "none"   # REQ-IAC-006-03
}
```

