### Stub Formation `.tflint.hcl` Variant

```hcl
# iac/terraform/formations/aws/<formation-name>/.tflint.hcl
# Stub formation — pfe-iac-modules module not yet available

plugin "aws" {
  enabled = true
  version = "0.32.0"
  source  = "github.com/terraform-linters/tflint-ruleset-aws"
}

rule "terraform_required_version" {
  enabled = true
}

rule "terraform_required_providers" {
  enabled = true
}

rule "terraform_naming_convention" {
  enabled = true
}

rule "terraform_deprecated_interpolation" {
  enabled = true
}

# Suppressed: Stub formation pending pfe-iac-modules v3.1.0 release (ECS service module).
# Variables declared to contract in variables.tf will be used once module is available.
# Tracked: https://github.com/mygainwell/mmes-cms-mbr/issues/142
# REQ-IAC-006-04: remove suppression when formation is completed.
rule "terraform_unused_declarations" {
  enabled = false
}

rule "terraform_module_pinned_source" {
  enabled          = true
  # Suppressed: git-SSH sources per STD-INFRA-IAC-002; PE-managed immutable semver tags.
  call_module_type = "none"
}
```

